parameters.jsCode:
// Generate verification token and expiry (production-safe)
try {
  const formData = $input.first().json;

  // Validate email format
  const email = formData['Email'] || formData.email || '';
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error('Invalid email format');
  }

  // Clean telegram username (remove @ if present)
  let telegram = formData['Telegram Username'] || formData.telegram || '';
  telegram = telegram.replace(/^@/, '').trim();
  if (!telegram) {
    throw new Error('Telegram username is required');
  }

  // Generate cryptographically secure token (without require)
  const token = Array.from({length: 64}, () => 
    Math.floor(Math.random() * 16).toString(16)
  ).join('');

  const tokenExpiry = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(); // 24 hours

  return [{
    json: {
      email: email.toLowerCase(),
      telegram: telegram,
      token: token,
      token_expiry: tokenExpiry,
      email_verified: false,
      telegram_verified: false,
      active: false,
      created_at: new Date().toISOString()
    }
  }];
} catch (error) {
  throw new Error(`Token generation failed: ${error.message}`);
}

const data = $('Generate Token').first().json;
const webhookUrl = $env.WEBHOOK_URL || 'http://localhost:5678';

const emailVerifyUrl = `${webhookUrl}/webhook/datatalk-verify-email?token=${data.token}&email=${encodeURIComponent(data.email)}`;
const telegramVerifyUrl = `${webhookUrl}/webhook/datatalk-verify-telegram?token=${data.token}&username=${data.telegram}`;

return [{
  json: {
    ...data,
    emailVerifyUrl,
    telegramVerifyUrl
  }
}];

